define("theme_learnlingo/storedfile_settings", [], function() { 'use strict'; /** * Select a background that contrasts with the image's visible pixels. * Transparent pixels must not make a white logo appear "dark". * * @param {HTMLImageElement} image Image being previewed. * @param {HTMLElement} container Preview background. */ const selectBackground = (image, container) => { if (!image.complete || !image.naturalWidth) { return; } try { const canvas = document.createElement('canvas'); canvas.width = 64; canvas.height = 64; const context = canvas.getContext('2d', {willReadFrequently: true}); if (!context) { return; } const scale = Math.min(64 / image.naturalWidth, 64 / image.naturalHeight); const width = image.naturalWidth * scale; const height = image.naturalHeight * scale; context.drawImage(image, (64 - width) / 2, (64 - height) / 2, width, height); const pixels = context.getImageData(0, 0, 64, 64).data; let sum = 0; let weight = 0; for (let i = 0; i < pixels.length; i += 4) { const alpha = pixels[i + 3] / 255; if (alpha < 0.12) { continue; } sum += (0.2126 * pixels[i] + 0.7152 * pixels[i + 1] + 0.0722 * pixels[i + 2]) * alpha; weight += alpha; } container.dataset.background = !weight ? 'neutral' : (sum / weight >= 148 ? 'dark' : 'light'); } catch (exception) { container.dataset.background = 'neutral'; } }; /** * Initialise one independent image setting. * * @param {HTMLElement} root */ const setup = (root) => { if (root.dataset.initialised === '1') { return; } root.dataset.initialised = '1'; const zone = root.querySelector('[data-file-dropzone]'); const choose = root.querySelector('[data-file-choose]'); const remove = root.querySelector('[data-file-delete]'); const input = root.querySelector('[data-file-input]'); const draft = root.querySelector('[data-file-draft]'); const picture = root.querySelector('[data-file-image]'); const empty = root.querySelector('[data-file-empty]'); const canvas = root.querySelector('[data-file-canvas]'); const name = root.querySelector('[data-file-name]'); const state = root.querySelector('[data-file-state]'); const status = root.querySelector('[data-file-status]'); let busy = false; let dragging = 0; picture.addEventListener('load', () => selectBackground(picture, canvas)); picture.addEventListener('error', () => { canvas.dataset.background = 'neutral'; }); if (picture.complete && picture.naturalWidth) { selectBackground(picture, canvas); } const show = (filename, url) => { const hasImage = Boolean(filename && url); empty.hidden = hasImage; picture.hidden = !hasImage; remove.hidden = !hasImage; state.textContent = hasImage ? root.dataset.currentLabel : root.dataset.emptyLabel; name.textContent = hasImage ? filename : root.dataset.noImageLabel; canvas.dataset.background = 'neutral'; if (hasImage) { picture.alt = filename; picture.src = url; if (picture.complete && picture.naturalWidth) { selectBackground(picture, canvas); } } else { picture.removeAttribute('src'); picture.alt = ''; } }; const setBusy = (active) => { busy = active; root.classList.toggle('ll-storedfile--busy', active); choose.disabled = active; remove.disabled = active; input.disabled = active; zone.setAttribute('aria-busy', active ? 'true' : 'false'); }; const request = async(action, file) => { if (busy || draft.disabled) { return; } setBusy(true); status.textContent = action === 'upload' ? root.dataset.uploadingLabel : root.dataset.deletingLabel; status.classList.remove('ll-storedfile__status--error'); const data = new FormData(); data.append('sesskey', root.dataset.sesskey); data.append('setting', root.dataset.setting); data.append('action', action); if (file) { data.append('image', file, file.name); } try { const response = await fetch(root.dataset.uploadUrl, { method: 'POST', body: data, credentials: 'same-origin' }); const result = await response.json(); if (!response.ok || !result.success) { throw new Error(result.message || root.dataset.errorLabel); } draft.value = String(result.draftid); show(result.filename, result.previewurl); status.textContent = action === 'upload' ? root.dataset.uploadedLabel : root.dataset.deletedLabel; } catch (error) { status.textContent = error.message || root.dataset.errorLabel; status.classList.add('ll-storedfile__status--error'); } finally { input.value = ''; setBusy(false); } }; choose.addEventListener('click', () => input.click()); input.addEventListener('change', () => { if (input.files && input.files.length) { request('upload', input.files[0]); } }); remove.addEventListener('click', () => { if (!busy && window.confirm(root.dataset.deleteConfirm)) { request('delete'); } }); zone.addEventListener('dragenter', (event) => { if (busy || draft.disabled || !event.dataTransfer || !Array.from(event.dataTransfer.types).includes('Files')) { return; } event.preventDefault(); dragging++; zone.classList.add('ll-storedfile__surface--dragging'); }); zone.addEventListener('dragover', (event) => { if (!busy && !draft.disabled && event.dataTransfer && Array.from(event.dataTransfer.types).includes('Files')) { event.preventDefault(); event.dataTransfer.dropEffect = 'copy'; } }); zone.addEventListener('dragleave', () => { dragging = Math.max(0, dragging - 1); if (!dragging) { zone.classList.remove('ll-storedfile__surface--dragging'); } }); zone.addEventListener('drop', (event) => { if (busy || draft.disabled) { return; } event.preventDefault(); dragging = 0; zone.classList.remove('ll-storedfile__surface--dragging'); if (event.dataTransfer && event.dataTransfer.files.length) { request('upload', event.dataTransfer.files[0]); } }); }; return { init: () => document.querySelectorAll('[data-ll-storedfile]').forEach(setup) }; });
